#!/usr/bin/env bun
import{mkdir,rm}from"node:fs/promises";import{readStdin}from"@monochromatic-dev/claude-code-plugins-hook-utils";async function ensureDir(dirPath){await mkdir(dirPath,{recursive:!0})}const STALE_DIST_ARTIFACTS=[`HEAD`,`config`,`hooks`,`objects`,`refs`,`.claude`];async function cleanDistArtifacts(workspaceRoot){let glob=new Bun.Glob(`packages/*/*/dist/final`),removals=[];for await(let finalDir of glob.scan({cwd:workspaceRoot,onlyFiles:!1}))for(let artifact of STALE_DIST_ARTIFACTS)removals.push(rm(`${workspaceRoot}/${finalDir}/${artifact}`,{recursive:!0,force:!0}));await Promise.all(removals)}async function removeMcpJson(workspaceRoot){await rm(`${workspaceRoot}/.mcp.json`,{force:!0})}const raw=await readStdin(),workspaceRoot=JSON.parse(raw).cwd;await Promise.all([ensureDir(`/tmp/claude`),ensureDir(`/tmp/claude-1000`),cleanDistArtifacts(workspaceRoot),removeMcpJson(workspaceRoot)]);export{};